import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const outputPath = resolve("public/discord-activity-bootstrap.js");
const check = process.argv.includes("--check");

const result = await build({
  entryPoints: ["src/browser/discord-activity-bootstrap.ts"],
  bundle: true,
  write: false,
  format: "esm",
  platform: "browser",
  target: ["es2022"],
  minify: true,
  legalComments: "eof",
  sourcemap: false,
  metafile: true,
  logLevel: "warning",
  banner: {
    js: "/* Generated by scripts/build-activity-bundle.mjs; do not edit directly. */",
  },
});

if (result.outputFiles.length !== 1) {
  throw new Error(`Expected one Activity bundle output, received ${result.outputFiles.length}.`);
}
const output = result.outputFiles[0].text;

if (check) {
  const committed = await readFile(outputPath, "utf8").catch(() => "");
  if (committed !== output) {
    throw new Error("The committed Discord Activity bundle is stale. Run npm run build:activity and commit the result.");
  }
  console.log("Discord Activity bundle is reproducible and current.");
} else {
  await writeFile(outputPath, output, "utf8");
  console.log(`Wrote ${outputPath} (${Buffer.byteLength(output)} bytes).`);
}
